//! Deterministic USD (`.usda`) export. Mapping table: SPEC.md Section 9.
//! Output is byte-deterministic for equal documents (golden-tested).

use std::collections::{HashMap, HashSet};

use serde_json::Value;

use crate::model::{JointType, SpatialDppDocument};

/// Export a document as an ASCII USDA layer.
pub fn export_usda(doc: &SpatialDppDocument) -> String {
    let mut out = String::new();
    out.push_str("#usda 1.0\n(\n");
    out.push_str(
        "    \"\"\"Generated by spatial-dpp v0.1.0 (https://github.com/daikiito-dk/Spatial-dpp-spec).\"\"\"\n\n",
    );
    out.push_str("    customLayerData = {\n");
    if let Ok(metadata_value) = serde_json::to_value(&doc.metadata) {
        out.push_str("        dictionary \"sdpp:metadata\" = {\n");
        emit_dict(&metadata_value, &mut out, 12);
        out.push_str("        }\n");
    }
    out.push_str(&format!(
        "        int \"sdpp:objectCount\" = {}\n",
        doc.objects.len()
    ));
    out.push_str("    }\n)\n\n");
    out.push_str("def Scope \"SpatialDPP\"\n{\n");

    let prim_names = assign_prim_names(doc);

    for object in &doc.objects {
        let name = prim_names
            .get(&object.id)
            .cloned()
            .unwrap_or_else(|| sanitize_prim_name(&object.id));
        out.push_str(&format!(
            "    def Xform \"{name}\" (prepend apiSchemas = [\"PhysicsRigidBodyAPI\"])\n    {{\n"
        ));
        out.push_str(&format!(
            "        custom string sdpp:label = \"{}\"\n",
            escape_usd_string(&object.label)
        ));
        let physical = &object.physical;
        out.push_str(&format!(
            "        double physics:mass = {}\n",
            physical.mass_kg
        ));
        if physical.center_of_mass.len() == 3 {
            out.push_str(&format!(
                "        custom double3 sdpp:centerOfMassNormalized = ({})\n",
                physical
                    .center_of_mass
                    .iter()
                    .map(|v| format!("{v}"))
                    .collect::<Vec<_>>()
                    .join(", ")
            ));
        }
        out.push_str(&format!(
            "        custom double sdpp:frictionStatic = {}\n",
            physical.friction.static_coefficient
        ));
        if let Some(kinetic) = physical.friction.kinetic {
            out.push_str(&format!(
                "        custom double sdpp:frictionKinetic = {kinetic}\n"
            ));
        }
        if let Some(density) = physical.density_kg_m3 {
            out.push_str(&format!(
                "        custom double sdpp:densityKgM3 = {density}\n"
            ));
        }
        out.push_str(&format!(
            "        custom double sdpp:youngsModulusPa = {}\n",
            physical.stiffness.youngs_modulus_pa
        ));
        if let Some(shear) = physical.stiffness.shear_modulus_pa {
            out.push_str(&format!(
                "        custom double sdpp:shearModulusPa = {shear}\n"
            ));
        }
        if let Some(poisson) = physical.stiffness.poisson_ratio {
            out.push_str(&format!(
                "        custom double sdpp:poissonRatio = {poisson}\n"
            ));
        }
        if let Ok(geometry_value) = serde_json::to_value(&object.geometry) {
            out.push_str("        custom dictionary sdpp:geometry = {\n");
            emit_dict(&geometry_value, &mut out, 12);
            out.push_str("        }\n");
        }
        if let Ok(compliance_value) = serde_json::to_value(&object.compliance) {
            out.push_str("        custom dictionary sdpp:compliance = {\n");
            emit_dict(&compliance_value, &mut out, 12);
            out.push_str("        }\n");
        }
        out.push_str("    }\n");
    }

    for object in &doc.objects {
        for joint in &object.physical.joints {
            let parent_prim = prim_names
                .get(&joint.parent)
                .cloned()
                .unwrap_or_else(|| sanitize_prim_name(&joint.parent));
            let child_prim = prim_names
                .get(&joint.child)
                .cloned()
                .unwrap_or_else(|| sanitize_prim_name(&joint.child));
            let joint_name = format!("joint_{}", sanitize_prim_name(&joint.id));
            let joint_class = match joint.joint_type {
                JointType::Revolute => "PhysicsRevoluteJoint",
                JointType::Prismatic => "PhysicsPrismaticJoint",
                JointType::Spherical | JointType::Fixed => "Xform",
            };
            out.push_str(&format!("    def {joint_class} \"{joint_name}\"\n    {{\n"));
            out.push_str(&format!(
                "        rel physics:body0 = </SpatialDPP/{parent_prim}>\n"
            ));
            out.push_str(&format!(
                "        rel physics:body1 = </SpatialDPP/{child_prim}>\n"
            ));
            out.push_str(&format!(
                "        custom string sdpp:jointType = \"{}\"\n",
                joint.joint_type.as_str()
            ));
            if let Some(axis) = &joint.axis {
                if axis.len() == 3 {
                    out.push_str(&format!(
                        "        custom double3 sdpp:axis = ({})\n",
                        axis.iter()
                            .map(|v| format!("{v}"))
                            .collect::<Vec<_>>()
                            .join(", ")
                    ));
                    if let Some(token) = canonical_axis_token(axis) {
                        out.push_str(&format!(
                            "        uniform token physics:axis = \"{token}\"\n"
                        ));
                    }
                }
            }
            if let Some(limits) = &joint.limits {
                if let Some(v) = limits.lower_deg {
                    out.push_str(&format!("        double physics:lowerLimit = {v}\n"));
                }
                if let Some(v) = limits.upper_deg {
                    out.push_str(&format!("        double physics:upperLimit = {v}\n"));
                }
                if let Some(v) = limits.lower_m {
                    out.push_str(&format!("        double physics:lowerLimit = {v}\n"));
                }
                if let Some(v) = limits.upper_m {
                    out.push_str(&format!("        double physics:upperLimit = {v}\n"));
                }
            }
            out.push_str("    }\n");
        }
    }

    out.push_str("}\n");
    out
}

fn canonical_axis_token(axis: &[f64]) -> Option<&'static str> {
    match axis {
        [x, y, z] if *x == 1.0 && *y == 0.0 && *z == 0.0 => Some("X"),
        [x, y, z] if *x == 0.0 && *y == 1.0 && *z == 0.0 => Some("Y"),
        [x, y, z] if *x == 0.0 && *y == 0.0 && *z == 1.0 => Some("Z"),
        _ => None,
    }
}

fn assign_prim_names(doc: &SpatialDppDocument) -> HashMap<String, String> {
    let mut taken: HashSet<String> = HashSet::new();
    let mut assigned: HashMap<String, String> = HashMap::new();
    for object in &doc.objects {
        let base = sanitize_prim_name(&object.id);
        let mut name = base.clone();
        let mut counter = 1;
        while taken.contains(&name) {
            counter += 1;
            name = format!("{base}_{counter}");
        }
        taken.insert(name.clone());
        assigned.insert(object.id.clone(), name);
    }
    assigned
}

fn sanitize_prim_name(id: &str) -> String {
    let mut out: String = id
        .chars()
        .map(|c| {
            if c.is_ascii_alphanumeric() || c == '_' {
                c
            } else {
                '_'
            }
        })
        .collect();
    if out.is_empty() {
        out.push('_');
    }
    if out.chars().next().is_some_and(|c| c.is_ascii_digit()) {
        out.insert(0, '_');
    }
    out
}

fn escape_usd_string(value: &str) -> String {
    value
        .replace('\\', "\\\\")
        .replace('"', "\\\"")
        .replace('\n', "\\n")
        .replace('\r', "\\r")
        .replace('\t', "\\t")
}

/// Emit USD dictionary entries for a JSON object. Keys are sorted (canonical
/// JSON) so output order is deterministic. Arrays of objects (e.g. the BOM)
/// become index-keyed dictionaries, which is valid USDA.
fn emit_dict(value: &Value, out: &mut String, indent: usize) {
    let Some(map) = value.as_object() else { return };
    for (key, entry) in map {
        emit_entry(key, entry, out, indent);
    }
}

fn emit_entry(key: &str, value: &Value, out: &mut String, indent: usize) {
    let pad = " ".repeat(indent);
    let quoted_key = format!("\"{}\"", escape_usd_string(key));
    match value {
        Value::String(s) => {
            out.push_str(&format!(
                "{pad}string {quoted_key} = \"{}\"\n",
                escape_usd_string(s)
            ));
        }
        Value::Bool(b) => out.push_str(&format!("{pad}bool {quoted_key} = {b}\n")),
        Value::Number(n) if n.is_i64() || n.is_u64() => {
            out.push_str(&format!("{pad}int {quoted_key} = {n}\n"));
        }
        Value::Number(n) => {
            out.push_str(&format!(
                "{pad}double {quoted_key} = {}\n",
                n.as_f64().unwrap_or_default()
            ));
        }
        Value::Object(_) => {
            out.push_str(&format!("{pad}dictionary {quoted_key} = {{\n"));
            emit_dict(value, out, indent + 4);
            out.push_str(&format!("{pad}}}\n"));
        }
        Value::Array(items) if items.is_empty() => {
            out.push_str(&format!("{pad}int[] {quoted_key} = []\n"));
        }
        Value::Array(items) if items.iter().all(Value::is_number) => {
            let numbers: Vec<String> = items
                .iter()
                .map(|v| format!("{}", v.as_f64().unwrap_or_default()))
                .collect();
            match items.len() {
                2 => out.push_str(&format!(
                    "{pad}double2 {quoted_key} = ({})\n",
                    numbers.join(", ")
                )),
                3 => out.push_str(&format!(
                    "{pad}double3 {quoted_key} = ({})\n",
                    numbers.join(", ")
                )),
                4 => out.push_str(&format!(
                    "{pad}double4 {quoted_key} = ({})\n",
                    numbers.join(", ")
                )),
                _ => out.push_str(&format!(
                    "{pad}double[] {quoted_key} = [{}]\n",
                    numbers.join(", ")
                )),
            }
        }
        Value::Array(items) if items.iter().all(Value::is_string) => {
            let strings: Vec<String> = items
                .iter()
                .filter_map(Value::as_str)
                .map(|s| format!("\"{}\"", escape_usd_string(s)))
                .collect();
            out.push_str(&format!(
                "{pad}string[] {quoted_key} = [{}]\n",
                strings.join(", ")
            ));
        }
        Value::Array(items) => {
            out.push_str(&format!("{pad}dictionary {quoted_key} = {{\n"));
            for (i, item) in items.iter().enumerate() {
                let inner = " ".repeat(indent + 4);
                out.push_str(&format!("{inner}dictionary \"{i}\" = {{\n"));
                emit_dict(item, out, indent + 8);
                out.push_str(&format!("{inner}}}\n"));
            }
            out.push_str(&format!("{pad}}}\n"));
        }
        Value::Null => {}
    }
}
